SELECT id, title, content, author_id as authorId, status, create_time as createTime, update_time as updateTime FROM announcement WHERE 1=1
AND id = #{id}
AND title LIKE CONCAT('%', #{title}, '%')
ORDER BY create_time DESC LIMIT #{pageNum}, #{pageSize}

SELECT COUNT(*) FROM announcement WHERE 1=1
AND id = #{id}
AND title LIKE CONCAT('%', #{title}, '%')

SELECT id, title, content, author_id as authorId, status, create_time as createTime, update_time as updateTime
FROM announcement
WHERE id = #{id}
